// Router request for the Nexora demo (same design as live). In: user_text, history[] (+ every field of the main workflow).
// Out: the same fields + gemini_body + route_decision 'smalltalk' ONLY for a pure greeting / thanks / goodbye (code, no model).
// «تمام» / «ok» are NOT fixed replies here: they can confirm a leave request the assistant is preparing.
const ROUTES = ['policy', 'hr_data', 'faq', 'work_advice', 'unclear'];
const input = $('Input').first().json;
const text = String(input.user_text ?? '');
const FIXED_WORDS = new Set(['السلام', 'عليكم', 'ورحمة', 'الله', 'وبركاته', 'سلام', 'صباح', 'مساء', 'الخير', 'النور', 'الفل', 'الورد',
  'اهلا', 'أهلا', 'اهلاً', 'أهلاً', 'هلا', 'هاي', 'يا', 'نور', 'hi', 'hello', 'hey', 'good', 'morning', 'evening', 'afternoon',
  'شكرا', 'شكراً', 'متشكر', 'متشكرة', 'متشكرين', 'تسلم', 'تسلمي', 'ميرسي', 'مرسي', 'جزيلا', 'جزيلاً', 'كتير', 'خالص', 'يخليك', 'جزاك', 'خيرا', 'خيراً',
  'thanks', 'thank', 'you', 'thx', 'ty', 'so', 'much', 'very', 'a', 'lot', 'مع', 'السلامة', 'باي', 'bye', 'goodbye', 'see', 'later']);
const words = text.toLowerCase().replace(/[^\p{L}\s]/gu, ' ').split(/\s+/).filter(Boolean);
const isFixed = words.length > 0 && words.length <= 6 && words.every((w) => FIXED_WORDS.has(w));

const INSTRUCTIONS = `<role>
You are the router of Nour, the internal HR assistant of Nexora Digital Solutions (نيكسورا), a company in Egypt.
Employees write in Arabic (formal or Egyptian dialect) or English.
Your only job: choose where the CURRENT message goes. You never answer it.
</role>

<routes>
policy: what the company HR policy SAYS: rules, entitlements and conditions (leaves, working hours, lateness and deductions, salaries, raises, overtime, advances, allowances, promotions, penalties, resignation, training).
  Examples: «إجازة الجواز كام يوم؟», «لو اتأخرت بيتخصم قد إيه؟», "Can I work from home?"

hr_data: the employee's OWN records (their leave balance, their requests and their status, their attendance and lateness, their profile, the latest memos) OR a request to DO something now: submit a leave, permission, mission or HR letter, or cancel a request.
  Examples: «رصيدي كام؟», «طلباتي فين؟», «اتأخرت كام مرة الشهر ده؟», «قدملي إجازة يوم الخميس», «الغي آخر طلب»

faq: HOW / WHERE / WHO questions about procedures and tools: how to use the HR system (بوابة نيكسورا), where to find something, how a request or document is processed, IT and access help, who to contact.
  Examples: «إزاي أقدم طلب من البوابة؟», «نسيت الباسورد أعمل إيه؟», «مين أكلم في الـ HR؟»

work_advice: anything else: advice on work situations, communication, productivity, career, general or technical questions, casual talk, what the assistant can do.
  Examples: «زميلي بيقاطعني في الاجتماعات», «إنت تقدر تساعدني في إيه؟»

unclear: no understandable request, even with the recent conversation (random letters, a lone word or symbol).
  Examples: «asdfgh», «؟»
</routes>

<rules>
1. Read the CURRENT message first. If it is understandable on its own, route it by itself, even if earlier messages were about another topic.
2. A short follow-up that depends on what was said before («وبعدين؟», «وإيه كمان؟», «طب ولو لسه مكملتش سنة؟») continues the topic of the LAST exchange (marked "last"): give it the route of that exchange.
3. A confirmation, refusal or missing detail («أيوه أكد», «تمام», «لا خلاص», a date, «يوم الخميس») for a request the assistant was preparing -> hr_data.
4. Own data or an action -> hr_data, even if the message also mentions a rule. What the rules allow -> policy. How / where to do it yourself -> faq.
5. A greeting together with a real question: route by the question.
</rules>

<output>
Answer ONLY with a JSON object: {"route": "<one of: policy, hr_data, faq, work_advice, unclear>"}.
</output>`;

const clean = (s, n) => { let t = String(s ?? '').split('📌')[0]; t = t.replace(/\(\s*\d+(?:\s*-\s*\d+)+[^)]*\)/g, '').replace(/\s+/g, ' ').trim(); return t.length > n ? t.slice(0, n) + '…' : t; };
const last3 = (Array.isArray(input.history) ? input.history : []).slice(-3);
const lines = last3.map((h, i) => `[${i + 1}${i === last3.length - 1 ? ' - last' : ''}] Employee: ${clean(h.text, 300)}\n    Nour: ${clean(h.response_text, 300) || '(no answer yet)'}`);
const conversation = ['Recent conversation (oldest first):', lines.length ? lines.join('\n') : '(none)', '', 'CURRENT message:', text].join('\n');
const gemini_body = { systemInstruction: { parts: [{ text: INSTRUCTIONS }] }, contents: [{ role: 'user', parts: [{ text: conversation }] }],
  generationConfig: { temperature: 0, maxOutputTokens: 50, responseMimeType: 'application/json', responseSchema: { type: 'OBJECT', properties: { route: { type: 'STRING', enum: ROUTES } }, required: ['route'] } } };
return [{ json: { ...input, route_decision: isFixed ? 'smalltalk' : '', decided_by: isFixed ? 'code' : null, gemini_body } }];

const ROUTES = ['policy', 'hr_data', 'faq', 'work_advice', 'unclear'];
const base = $('Build Router Request').first().json;
const msg = (e) => (typeof e === 'string' ? e : (e?.message ?? JSON.stringify(e))).slice(0, 250);
let route = 'router_error', error = null;
if ($json.error) error = 'gemini: ' + msg($json.error);
else { const raw = ($json.candidates?.[0]?.content?.parts || []).map((p) => p.text || '').join(''); try { const r = JSON.parse(raw).route; if (ROUTES.includes(r)) route = r; else error = 'gemini: unexpected route ' + String(r).slice(0, 50); } catch (e) { error = 'gemini: not JSON'; } }
return [{ json: { ...base, route_decision: route, decided_by: 'gemini', router_model: $json?.modelVersion ?? 'gemini-3.5-flash-lite', router_error: error } }];

const ROUTES = ['policy', 'hr_data', 'faq', 'work_advice', 'unclear'];
const base = $('Read Gemini Route').first().json;
const msg = (e) => (typeof e === 'string' ? e : (e?.message ?? JSON.stringify(e))).slice(0, 250);
let route = 'router_failed', error = null;
if ($json.error) error = 'gemini-3.1: ' + msg($json.error);
else { const raw = ($json.candidates?.[0]?.content?.parts || []).map((p) => p.text || '').join(''); try { const r = JSON.parse(raw).route; if (ROUTES.includes(r)) route = r; else error = 'gemini-3.1: unexpected route'; } catch (e) { error = 'gemini-3.1: not JSON'; } }
return [{ json: { ...base, route_decision: route, decided_by: 'gemini_3.1_fallback', router_model: $json?.modelVersion ?? 'gemini-3.1-flash-lite', router_error: [base.router_error, error].filter(Boolean).join(' | ') } }];

// Output: every input field + route_decision + router{decided_by, model, error}. The model request is dropped.
const { gemini_body, decided_by, router_model, router_error, ...rest } = $json;
return [{ json: { ...rest, router: { decided_by: decided_by ?? 'unknown', model: router_model ?? null, error: router_error ? String(router_error).slice(0, 300) : null } } }];
